// Dart
const channel = MethodChannel('com.app/device');
final level = await channel.invokeMethod<int>('batteryLevel');

// Swift — AppDelegate
let channel = FlutterMethodChannel(name: "com.app/device",
                                   binaryMessenger: controller.binaryMessenger)
channel.setMethodCallHandler { call, result in
  switch call.method {
  case "batteryLevel": result(Int(UIDevice.current.batteryLevel * 100))
  default: result(FlutterMethodNotImplemented)
  }
}

// Kotlin — MainActivity
MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "com.app/device")
  .setMethodCallHandler { call, result ->
    when (call.method) {
      "batteryLevel" -> result.success(batteryLevel())
      else -> result.notImplemented()
    }
  }

// Dart
const events = EventChannel('com.app/connectivity');
final sub = events.receiveBroadcastStream()
    .listen((status) => debugPrint('status: $status'));

// Kotlin
EventChannel(messenger, "com.app/connectivity").setStreamHandler(
  object : EventChannel.StreamHandler {
    override fun onListen(args: Any?, sink: EventChannel.EventSink) {
      register { status -> sink.success(status) }
    }
    override fun onCancel(args: Any?) { unregister() }
  }
)

